mapper.select:
select 

where settings.rule_version_id = #{ruleVersionId}
  and settings.evaluation_year = #{evaluationYear}
  and settings.achievement_area_code = #{achievementAreaCode}
  and settings.achievement_category_code = #{achievementCategoryCode}
  and settings.management_item_code = #{managementItemCode}
  and settings.researcher_count_band = #{researcherCountBand}
  and settings.participation_type_code = #{participationTypeCode}
limit 1
